using UnityEngine;
using UnityEngine.UI;
namespace CampaignDemo {
 // Fixed world-space paper markings: neither ticks nor text depend on the viewport.
 public sealed class PaperMapBorder:MonoBehaviour {
  public Rect Bounds {get;private set;}public int CoordinateLabels {get;private set;}
  Material lineMaterial;Material clippedPaper;
  public static float Bite(float t,int side){float s=side*7.13f;float wave=.024f+.017f*Mathf.Sin(t*4.7f+s)+.012f*Mathf.Sin(t*13.1f+s);return Mathf.Max(.008f,wave+Mathf.Pow(Mathf.Max(0,Mathf.Sin(t*1.71f+s)),28)*(.13f+.09f*Mathf.Sin(t*.31f+s)));}
  public void Build(FreeMarchMapRuntime map){var b=map.definition.bounds;var a=map.transform.TransformPoint(b.min);var z=map.transform.TransformPoint(b.max);Bounds=Rect.MinMaxRect(a.x,a.y,z.x,z.y);var cart=map.GetComponent<StaffMapCartography>();if(cart!=null)cart.ShowBakedBackground();lineMaterial=new Material(Shader.Find("Sprites/Default"));clippedPaper=new Material(Shader.Find("Campaign/WornMapPaper"));clippedPaper.SetVector("_MapRect",new Vector4(Bounds.xMin,Bounds.yMin,Bounds.xMax,Bounds.yMax));
   foreach(var renderer in FindObjectsOfType<SpriteRenderer>()){if(renderer.name.Contains("atlas")||renderer.name.StartsWith("Paper shadow"))continue;if(renderer.bounds.size.x>=Bounds.width*.98f&&renderer.bounds.size.y>=Bounds.height*.98f&&renderer.sortingOrder>=-70){var material=new Material(clippedPaper);if(renderer.sharedMaterial!=null&&renderer.sharedMaterial.HasProperty("_MainTex"))material.mainTexture=renderer.sharedMaterial.mainTexture;renderer.sharedMaterial=material;}}
   AddMarginalia();DrawBrokenGrid();for(int side=0;side<4;side++)Edge(side);
   const float step=5;for(float x=Mathf.Ceil(Bounds.xMin/step)*step;x<Bounds.xMax-.7f;x+=step){if(x<Bounds.xMin+.7f)continue;Tick(new Vector2(x,Bounds.yMin+.38f),Vector2.up);Tick(new Vector2(x,Bounds.yMax-.38f),Vector2.down);Caption(x.ToString("0"),new Vector3(x,Bounds.yMin+.86f,-.08f),0);Caption(x.ToString("0"),new Vector3(x,Bounds.yMax-.86f,-.08f),0);}
   for(float y=Mathf.Ceil(Bounds.yMin/step)*step;y<Bounds.yMax-.7f;y+=step){if(y<Bounds.yMin+.7f)continue;Tick(new Vector2(Bounds.xMin+.38f,y),Vector2.right);Tick(new Vector2(Bounds.xMax-.38f,y),Vector2.left);Caption(y.ToString("0"),new Vector3(Bounds.xMin+.86f,y,-.08f),90);Caption(y.ToString("0"),new Vector3(Bounds.xMax-.86f,y,-.08f),-90);}
  }
  void AddMarginalia(){
   var outer=new Rect(Bounds.xMin-6,Bounds.yMin-7,Bounds.width+12,Bounds.height+14);
   var texture=new Texture2D(256,256,TextureFormat.RGB24,false);texture.wrapMode=TextureWrapMode.Repeat;var pixels=new Color[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++){float grain=StaffMapCanvas.Hash(x,y,319)-.5f;float stain=StaffMapCanvas.Noise(x/35f,y/35f,217);pixels[y*256+x]=new Color(.83f,.81f,.74f)*(1+grain*.022f-stain*.025f);}texture.SetPixels(pixels);texture.Apply();
   var paper=new GameObject("Map title and legend paper margin");paper.transform.SetParent(transform,false);paper.transform.position=new Vector3(outer.center.x,outer.center.y,.1f);var sprite=paper.AddComponent<SpriteRenderer>();sprite.sprite=Sprite.Create(texture,new Rect(0,0,256,256),Vector2.one*.5f,100,0,SpriteMeshType.FullRect);sprite.drawMode=SpriteDrawMode.Sliced;sprite.size=outer.size;sprite.sortingOrder=2;var material=new Material(clippedPaper);material.SetVector("_MapRect",new Vector4(outer.xMin,outer.yMin,outer.xMax,outer.yMax));sprite.sharedMaterial=material;
   Frame(new Rect(Bounds.xMin-.09f,Bounds.yMin-.09f,Bounds.width+.18f,Bounds.height+.18f),.065f);
   Frame(new Rect(Bounds.xMin-.27f,Bounds.yMin-.27f,Bounds.width+.54f,Bounds.height+.54f),.026f);
   Print("DOUBLE VALLEY",new Vector2(Bounds.center.x,Bounds.yMax+4.3f),.42f,FontStyle.Bold);
   Print("FIELD OPERATIONS MAP",new Vector2(Bounds.center.x,Bounds.yMax+2.2f),.15f,FontStyle.Normal);
   Print("SHEET 01",new Vector2(Bounds.xMin+4,Bounds.yMax+2.5f),.15f,FontStyle.Normal);
   Print("NORTH UP",new Vector2(Bounds.xMax-5,Bounds.yMax+2.5f),.13f,FontStyle.Normal);
   var c=new Vector2(Bounds.xMax+3,Bounds.center.y);Stroke("North south axis",new[]{(Vector3)(c+Vector2.down*2),(Vector3)(c+Vector2.up*2)},.045f,StaffMapStyle.Ink);Stroke("East west axis",new[]{(Vector3)(c+Vector2.left*1.2f),(Vector3)(c+Vector2.right*1.2f)},.025f,StaffMapStyle.Ink);Stroke("North arrow",new[]{(Vector3)(c+new Vector2(-.5f,1.3f)),(Vector3)(c+new Vector2(0,2)),(Vector3)(c+new Vector2(.5f,1.3f))},.045f,StaffMapStyle.Ink);Print("N",c+Vector2.up*2.8f,.18f,FontStyle.Bold);Print("S",c+Vector2.down*2.8f,.15f,FontStyle.Normal);Print("W",c+Vector2.left*1.9f,.12f,FontStyle.Normal);Print("E",c+Vector2.right*1.9f,.12f,FontStyle.Normal);
   InkDrops();float yLegend=Bounds.yMin-4.5f;Print("CONVENTIONAL SIGNS",new Vector2(Bounds.center.x,Bounds.yMin-1.9f),.17f,FontStyle.Bold);
   LegendCircle(new Vector2(Bounds.xMin+5,yLegend),.35f,StaffMapStyle.Blue);Print("Settlement",new Vector2(Bounds.xMin+11,yLegend),.13f,FontStyle.Normal);
   LegendCircle(new Vector2(Bounds.xMin+24,yLegend),.35f,new Color(.65f,.49f,.09f));Print("Resources",new Vector2(Bounds.xMin+30,yLegend),.13f,FontStyle.Normal);
   Stroke("Road legend",new[]{new Vector3(Bounds.center.x-7,yLegend,0),new Vector3(Bounds.center.x-4,yLegend,0)},.035f,StaffMapStyle.Ink);Print("Road",new Vector2(Bounds.center.x,yLegend),.13f,FontStyle.Normal);
   Stroke("River legend",new[]{new Vector3(Bounds.center.x+12,yLegend,0),new Vector3(Bounds.center.x+15,yLegend,0)},.14f,new Color(.34f,.45f,.49f));Print("River",new Vector2(Bounds.center.x+19,yLegend),.13f,FontStyle.Normal);
   Print("GRID INTERVAL  5 km",new Vector2(Bounds.xMax-11,yLegend),.12f,FontStyle.Normal);
  }
  void Frame(Rect r,float width){
   var vertices=new System.Collections.Generic.List<Vector3>();var colors=new System.Collections.Generic.List<Color>();var triangles=new System.Collections.Generic.List<int>();var corners=new[]{new Vector2(r.xMin,r.yMin),new Vector2(r.xMax,r.yMin),new Vector2(r.xMax,r.yMax),new Vector2(r.xMin,r.yMax)};
   for(int side=0;side<4;side++){var start=corners[side];var delta=corners[(side+1)%4]-start;float length=delta.magnitude;var along=delta.normalized;var normal=new Vector2(-along.y,along.x);int count=Mathf.CeilToInt(length/.37f);for(int i=0;i<count;i++){float random=StaffMapCanvas.Hash(i,side,739);float low=i*length/count,high=(i+1f)*length/count;if(random<.055f)continue;float gap=random<.19f?.06f:.006f;var p=start+along*(low+gap);var q=start+along*(high-gap*.2f);float jitter=(StaffMapCanvas.Hash(i,side,978)-.5f)*.018f;float stroke=width*Mathf.Lerp(.58f,1.3f,StaffMapCanvas.Hash(i,side,881));var color=new Color(.12f,.115f,.09f,Mathf.Lerp(.45f,.94f,random));FrameQuad(p+normal*jitter,q+normal*jitter,normal*stroke*.5f,color,vertices,colors,triangles);if(random>.76f)FrameQuad(p+normal*width,q+normal*width,normal*width*1.6f,new Color(.20f,.16f,.10f,.075f),vertices,colors,triangles);}}
   var mesh=new Mesh{name="Weathered double border ink"};mesh.SetVertices(vertices);mesh.SetColors(colors);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();var g=new GameObject("Dirty double map frame",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(transform,false);g.transform.position=Vector3.zero;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=lineMaterial;g.GetComponent<MeshRenderer>().sortingOrder=28;
  }
  void FrameQuad(Vector2 a,Vector2 b,Vector2 n,Color color,System.Collections.Generic.List<Vector3> vertices,System.Collections.Generic.List<Color> colors,System.Collections.Generic.List<int> triangles){int index=vertices.Count;vertices.Add(new Vector3(a.x-n.x,a.y-n.y,-.055f));vertices.Add(new Vector3(a.x+n.x,a.y+n.y,-.055f));vertices.Add(new Vector3(b.x+n.x,b.y+n.y,-.055f));vertices.Add(new Vector3(b.x-n.x,b.y-n.y,-.055f));for(int i=0;i<4;i++)colors.Add(color);triangles.Add(index);triangles.Add(index+1);triangles.Add(index+2);triangles.Add(index);triangles.Add(index+2);triangles.Add(index+3);}
  void InkDrops(){var positions=new[]{new Vector2(Bounds.xMin-3,Bounds.center.y+12),new Vector2(Bounds.xMax+2.6f,Bounds.yMin-3.6f),new Vector2(Bounds.center.x+22,Bounds.yMax+5.4f),new Vector2(Bounds.xMin-3.6f,Bounds.yMin-3.3f),new Vector2(Bounds.xMax+3.3f,Bounds.yMax+3.5f)};
   for(int mark=0;mark<positions.Length;mark++){const int size=128;var texture=new Texture2D(size,size,TextureFormat.RGBA32,false);texture.filterMode=FilterMode.Bilinear;var pixels=new Color[size*size];var random=new System.Random(217+mark*397);var centers=new System.Collections.Generic.List<Vector2>{new Vector2(64,64)};var radii=new System.Collections.Generic.List<float>{14+mark%3*3};for(int i=0;i<14;i++){float angle=(float)random.NextDouble()*Mathf.PI*2;float distance=17+(float)random.NextDouble()*31;centers.Add(new Vector2(64+Mathf.Cos(angle)*distance,64+Mathf.Sin(angle)*distance));radii.Add(1+(float)random.NextDouble()*3.5f);}for(int y=0;y<size;y++)for(int x=0;x<size;x++){float alpha=0;for(int i=0;i<centers.Count;i++){var d=new Vector2(x,y)-centers[i];float radius=radii[i]*(1+(StaffMapCanvas.Noise(x*.25f,y*.25f,mark+19)-.5f)*.24f);float distance=d.magnitude;float body=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(radius*.65f,radius*1.05f,distance));float halo=Mathf.Exp(-distance*distance/(radius*radius*2.1f))*.13f;alpha=Mathf.Max(alpha,Mathf.Clamp01(body*(i==0?.78f:.55f)+halo));}pixels[y*size+x]=new Color(.08f,.075f,.06f,alpha);}texture.SetPixels(pixels);texture.Apply();var g=new GameObject("Old ink drop "+mark);g.transform.SetParent(transform,false);g.transform.position=new Vector3(positions[mark].x,positions[mark].y,-.075f);g.transform.localRotation=Quaternion.Euler(0,0,mark*53);g.transform.localScale=Vector3.one*1.6f;var renderer=g.AddComponent<SpriteRenderer>();renderer.sprite=Sprite.Create(texture,new Rect(0,0,size,size),Vector2.one*.5f,90);renderer.color=new Color(1,1,1,.85f);renderer.sortingOrder=27;}
  }
  void LegendCircle(Vector2 centre,float radius,Color color){var points=new Vector3[33];for(int i=0;i<points.Length;i++){float a=i*Mathf.PI*2/32;points[i]=new Vector3(centre.x+Mathf.Cos(a)*radius,centre.y+Mathf.Sin(a)*radius,-.06f);}Stroke("Legend point symbol",points,.07f,color);}
  void Print(string value,Vector2 point,float size,FontStyle style){var g=new GameObject("Map marginalia · "+value);g.transform.SetParent(transform,false);g.transform.position=new Vector3(point.x,point.y,-.08f);var text=g.AddComponent<TextMesh>();text.font=TabletopPresentation.MapFont;text.fontSize=64;text.fontStyle=style;text.characterSize=size;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=new Color(.21f,.20f,.17f);text.text=value;var renderer=g.GetComponent<MeshRenderer>();renderer.sharedMaterial=text.font.material;renderer.sortingOrder=29;}
  void DrawBrokenGrid(){
   var vertices=new System.Collections.Generic.List<Vector3>();var colors=new System.Collections.Generic.List<Color>();var triangles=new System.Collections.Generic.List<int>();
   const float step=5;for(float x=Mathf.Ceil(Bounds.xMin/step)*step;x<Bounds.xMax-.7f;x+=step)if(x>Bounds.xMin+.7f)GridStroke(new Vector2(x,Bounds.yMin+.38f),new Vector2(x,Bounds.yMax-.38f),17,vertices,colors,triangles);
   for(float y=Mathf.Ceil(Bounds.yMin/step)*step;y<Bounds.yMax-.7f;y+=step)if(y>Bounds.yMin+.7f)GridStroke(new Vector2(Bounds.xMin+.38f,y),new Vector2(Bounds.xMax-.38f,y),41,vertices,colors,triangles);
   var mesh=new Mesh{name="Broken ink coordinate grid"};if(vertices.Count>65535)mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetColors(colors);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();
   var g=new GameObject("Map coordinate grid · broken ink",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(transform,false);g.transform.position=Vector3.zero;g.GetComponent<MeshFilter>().sharedMesh=mesh;var renderer=g.GetComponent<MeshRenderer>();renderer.sharedMaterial=lineMaterial;renderer.sortingOrder=5;
  }
  void GridStroke(Vector2 a,Vector2 b,int salt,System.Collections.Generic.List<Vector3> vertices,System.Collections.Generic.List<Color> colors,System.Collections.Generic.List<int> triangles){
   float length=Vector2.Distance(a,b);var direction=(b-a).normalized;var normal=new Vector2(-direction.y,direction.x);int count=Mathf.CeilToInt(length/.55f);
   for(int i=0;i<count;i++){float random=StaffMapCanvas.Hash(Mathf.RoundToInt(a.x*37+a.y*19),i,salt+217);if(random<.19f)continue;float start=i/(float)count,end=Mathf.Min(1,(i+1f)/count);float pressure=StaffMapCanvas.Noise(a.x+direction.x*i*.71f,a.y+direction.y*i*.71f,salt);float gap=Mathf.Lerp(.012f,.12f,StaffMapCanvas.Hash(i,salt,941));var p=a+direction*(start*length+gap);var q=a+direction*(end*length-gap*.4f);var n=normal*Mathf.Lerp(.009f,.016f,pressure);var ink=new Color(.13f,.13f,.11f,Mathf.Lerp(.25f,.55f,pressure)*Mathf.Lerp(.65f,1,random));int v=vertices.Count;vertices.Add(new Vector3(p.x-n.x,p.y-n.y,-.018f));vertices.Add(new Vector3(p.x+n.x,p.y+n.y,-.018f));vertices.Add(new Vector3(q.x+n.x,q.y+n.y,-.018f));vertices.Add(new Vector3(q.x-n.x,q.y-n.y,-.018f));for(int k=0;k<4;k++)colors.Add(ink);triangles.Add(v);triangles.Add(v+1);triangles.Add(v+2);triangles.Add(v);triangles.Add(v+2);triangles.Add(v+3);}
  }
  void Edge(int side){bool vertical=side<2;float lo=vertical?Bounds.yMin:Bounds.xMin,hi=vertical?Bounds.yMax:Bounds.xMax;int count=Mathf.CeilToInt((hi-lo)/.08f)+1;var points=new Vector3[count];for(int i=0;i<count;i++){float t=Mathf.Lerp(lo,hi,i/(float)(count-1));float inset=Bite(t,side)+.14f;points[i]=side==0?new Vector3(Bounds.xMin+inset,t,-.04f):side==1?new Vector3(Bounds.xMax-inset,t,-.04f):side==2?new Vector3(t,Bounds.yMin+inset,-.04f):new Vector3(t,Bounds.yMax-inset,-.04f);}Stroke("Weathered map neatline",points,.035f,new Color(.14f,.13f,.10f,.78f));}
  void Tick(Vector2 point,Vector2 inward){Stroke("Paper coordinate tick",new[]{new Vector3(point.x,point.y,-.06f),new Vector3(point.x+inward.x*.25f,point.y+inward.y*.25f,-.06f)},.035f,StaffMapStyle.Ink);}
  void Stroke(string title,Vector3[] points,float width,Color color){var g=new GameObject(title);g.transform.SetParent(transform,false);var line=g.AddComponent<LineRenderer>();line.sharedMaterial=lineMaterial;line.useWorldSpace=true;line.positionCount=points.Length;line.SetPositions(points);line.startWidth=line.endWidth=width;line.startColor=line.endColor=color;line.sortingOrder=28;}
  void Caption(string value,Vector3 position,float rotation){var g=new GameObject("Paper coordinate "+value);g.transform.SetParent(transform,false);g.transform.SetPositionAndRotation(position,Quaternion.Euler(0,0,rotation));var text=g.AddComponent<TextMesh>();text.font=TabletopPresentation.MapFont;text.text=value;text.fontSize=48;text.characterSize=.14f;text.anchor=TextAnchor.MiddleCenter;text.color=StaffMapStyle.Ink;var renderer=g.GetComponent<MeshRenderer>();renderer.sharedMaterial=text.font.material;renderer.sortingOrder=29;CoordinateLabels++;}
 }
}
